// /quote — generated by Bot Studio
const { createCommandBuilder } = require('../utils/builders');
const { AttachmentBuilder, ChannelType } = require('discord.js');

/**
 * Converts any escaped newline sequences (\\n, \\r\\n, etc.)
 * into real newlines, then collapses excessive blank lines.
 */
function normalizeNewlines(text) {
  if (!text) return '';
  return String(text)
    .replace(/\\r\\n/g, '\n')
    .replace(/\\n/g, '\n')
    .replace(/\\r/g, '\n')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

/**
 * Force Excel to treat a value as text via ="value" formula.
 * Prevents large Discord snowflake IDs from scientific notation.
 */
function csvId(value) {
  return `"=""${String(value ?? '')}"""`;
}

/** Standard CSV escape for non-ID fields. */
const csvEscape = value => `"${String(value ?? '').replace(/"/g, '""')}"`;

/** Extract all 9–13 digit standalone numbers from text (Discord snowflake IDs). */
function extractIds(text) {
  if (!text) return [];
  const matches = text.match(/\b\d{9,13}\b/g);
  return matches ? [...new Set(matches)] : [];
}

/** Build a single CSV data row. */
function buildRow(inputLink, status, authorTag, authorId, createdAt, channelId, messageId, content, attachmentUrls, extractedIds) {
  return [
    csvEscape(inputLink),
    csvEscape(status),
    csvEscape(authorTag),
    csvId(authorId),
    csvEscape(createdAt),
    csvId(channelId),
    csvId(messageId),
    csvEscape(content),
    csvEscape(attachmentUrls),
    csvEscape(extractedIds),
  ].join(',');
}

/**
 * Resolve a channel that might be:
 *  - a regular text channel
 *  - a thread (PublicThread / PrivateThread / AnnouncementThread)
 *  - a forum post thread (the channelId IN a forum link IS the thread id)
 *
 * For forum links the structure is: /channels/guildId/threadId/messageId
 * The threadId is already a thread channel — fetch it directly.
 */
async function resolveChannel(client, channelId) {
  const channel = await client.channels.fetch(channelId);
  if (!channel) throw new Error('Channel not found');

  // Thread types — can fetch messages directly
  const threadTypes = [
    ChannelType.PublicThread,
    ChannelType.PrivateThread,
    ChannelType.AnnouncementThread,
  ];

  if (threadTypes.includes(channel.type) || channel.isThread?.()) {
    return channel;
  }

  if (channel.isTextBased()) {
    return channel;
  }

  throw new Error('Channel not accessible or not text-based');
}

module.exports = {
  data: createCommandBuilder({
    name: 'quote',
    description: 'Quote one or more Discord messages by pasting their links',
    configure: builder =>
      builder.addStringOption(opt =>
        opt
          .setName('links')
          .setDescription('Paste message links separated by spaces (max 10)')
          .setRequired(true)
      ),
  }),

  async execute(interaction) {
    await interaction.deferReply({ ephemeral: false });

    const raw    = interaction.options.getString('links');
    const linkRe = /https?:\/\/(?:ptb\.|canary\.)?discord(?:app)?\.com\/channels\/(\d+)\/(\d+)\/(\d+)/g;
    const links  = [...raw.matchAll(linkRe)].map(m => m[0]).slice(0, 10);

    if (!links.length) {
      return interaction.editReply('❌ No valid Discord message links found.');
    }

    const parseLink = url => {
      const m = url.match(/channels\/(\d+)\/(\d+)\/(\d+)/);
      return m ? { guildId: m[1], channelId: m[2], messageId: m[3] } : null;
    };

    // Header row
    const csvRows = [
      [
        csvEscape('input_link'),
        csvEscape('status'),
        csvEscape('author_tag'),
        csvEscape('author_id'),
        csvEscape('created_at'),
        csvEscape('channel_id'),
        csvEscape('message_id'),
        csvEscape('content'),
        csvEscape('attachment_urls'),
        csvEscape('extracted_ids_in_content'),
      ].join(','),
    ];

    let first = true;

    const send = async content => {
      if (first) {
        await interaction.editReply(content);
        first = false;
      } else {
        await interaction.followUp({ content, ephemeral: false });
      }
    };

    /** Core format logic — builds both the Discord reply and the CSV row. */
    const processMessage = async (msg, inputLink) => {
      const tag = msg.author.discriminator && msg.author.discriminator !== '0'
        ? `${msg.author.username}#${msg.author.discriminator}`
        : msg.author.username;

      const authorId = msg.author.id;

      const dateStr = new Date(msg.createdTimestamp).toLocaleString('en-US', {
        month:   'numeric',
        day:     'numeric',
        year:    'numeric',
        hour:    'numeric',
        minute:  '2-digit',
        second:  '2-digit',
        hour12:  true,
      });

      const content = normalizeNewlines(msg.content || '');
      const foundIds = extractIds(content);

      const parts = [`**${tag}** — ${dateStr}`];
      if (content) parts.push(content);
      if (msg.attachments.size > 0) {
        for (const att of msg.attachments.values()) {
          parts.push(`📎 [${att.name || 'file'}](${att.url})`);
        }
      }
      parts.push(`Original: <#${msg.channelId}> 🌊`);

      const attachmentUrls = msg.attachments.size > 0
        ? [...msg.attachments.values()].map(a => a.url).join(' | ')
        : '';

      csvRows.push(buildRow(
        inputLink, 'quoted', tag, authorId, dateStr,
        msg.channelId, msg.id, content, attachmentUrls,
        foundIds.join(' | '),
      ));

      return { out: parts.join('\n\n'), foundIds };
    };

    /**
     * Try to fetch a message by ID from a known channel.
     * For extracted IDs, the message lives in the same thread/channel
     * as the parent message — pass that channel object directly.
     */
    const fetchMessage = async (channel, messageId) => {
      return channel.messages.fetch(messageId);
    };

    for (const link of links) {
      const parsed = parseLink(link);

      if (!parsed) {
        csvRows.push(buildRow(link, 'invalid_link', '', '', '', '', '', '', '', ''));
        await send(`❌ Invalid link: ${link}`);
        continue;
      }

      let channel;
      try {
        // resolveChannel handles text channels, threads, AND forum post threads
        channel = await resolveChannel(interaction.client, parsed.channelId);
      } catch (err) {
        csvRows.push(buildRow(link, 'fetch_failed', '', '', '', parsed.channelId, parsed.messageId, '', '', ''));
        await send(`❌ Could not access channel for: ${link}`);
        continue;
      }

      try {
        const msg = await fetchMessage(channel, parsed.messageId);
        const { out, foundIds } = await processMessage(msg, link);
        await send(out);

        // ── Fetch messages found by snowflake ID inside the content ──
        for (const id of foundIds) {
          try {
            const linkedMsg = await fetchMessage(channel, id);
            const { out: linkedOut } = await processMessage(linkedMsg, `extracted:${id}`);
            await send(`↳ **Extracted message** (ID \`${id}\`):\n\n${linkedOut}`);
          } catch (_) {
            // Not a valid message ID in this channel — log but don't error
            csvRows.push(buildRow(
              `extracted:${id}`, 'fetch_failed', '', '', '',
              channel.id, id, '', '', '',
            ));
          }
        }

      } catch (err) {
        csvRows.push(buildRow(link, 'fetch_failed', '', '', '', parsed.channelId, parsed.messageId, '', '', ''));
        await send(`❌ Could not fetch message: ${link}`);
      }
    }

    // ── CSV export ─────────────────────────────────────────────────────
    if (csvRows.length > 1) {
      const csv  = csvRows.join('\n');
      const file = new AttachmentBuilder(Buffer.from(csv, 'utf8'), {
        name: `quote-${Date.now()}.csv`,
      });

      try {
        await interaction.user.send({ content: '📄 CSV export of quote results:', files: [file] });
        await interaction.followUp({ content: '✅ Sent CSV export to your DMs.', ephemeral: true });
      } catch (_) {
        await interaction.followUp({ content: '📄 CSV export of quote results:', files: [file], ephemeral: false });
      }
    }
  },
};